from __future__ import annotations

import base64, gzip

SECTORS = ['UNKNOWN','가정용품과개인용품','건강관리장비와서비스','교육서비스','기술하드웨어와장비','내구소비재와의류','다각화된금융','디스플레이','미디어와엔터테인먼트','반도체와반도체장비','보험','부동산','상업서비스와공급품','소매(유통)','소재','소프트웨어와서비스','식품,음료,담배','식품과기본식료품소매','에너지','운송','유틸리티','은행','자동차와부품','자본재','전기통신서비스','전자와 전기제품','제약과생물공학','증권','호텔,레스토랑,레저등']

_B64 = '''



'''

def wics_map() -> dict[str, str]:
    raw = gzip.decompress(base64.b64decode(''.join(_B64.split()))).decode('utf-8')
    out = {}
    for line in raw.splitlines():
        code, sid = line.split(',')
        out[code] = SECTORS[int(sid)]
    return out
